    expected(kind, object_count, digest) AS (VALUES
        ('relations', 39, '8b7c92be0f2fd5402a424d95eea5233a'),
        ('columns', 629, '5b45839a79986b7f09e97d9c18ab2ebb'),
        ('constraints', 855, '486df24518366f36689d83135245b0fa'),
        ('indexes', 239, 'caa0c0ba455c58af334ea02bd0afa319'),
        ('functions', 3, '92c2ea81850bf9cb5357e173476705f7'),
        ('triggers', 17, 'abbe0bced5705576cfce1a2dc2e0e615')
    )
    SELECT pg_catalog.count(*) INTO mismatch_count
    FROM expected
    FULL JOIN observed USING (kind)
    WHERE observed.kind IS NULL OR expected.kind IS NULL
       OR observed.object_count IS DISTINCT FROM expected.object_count
       OR observed.digest IS DISTINCT FROM expected.digest;
    IF mismatch_count <> 0 THEN
