        ('readmodel', 'public_offer', 'public_product_card_id', 'public product card id'),
        ('readmodel', 'public_offer', 'offer_id', 'ショップ単位の販売Offer。'),
        ('readmodel', 'public_offer', 'shop_id', 'shop id'),
        ('readmodel', 'public_offer', 'shop_name', 'shop name'),
        ('readmodel', 'public_offer', 'price_jpy', 'price jpy'),
        ('readmodel', 'public_offer', 'shipping_fee_jpy', 'shipping fee jpy'),
