        ('readmodel', 'runtime_control', 'site_id', '対象サイト。MVPは1サイトだが将来の複数サイトを識別可能にする。'),
        ('readmodel', 'runtime_control', 'scope_type', 'scope type'),
        ('readmodel', 'runtime_control', 'scope_id', 'scope id'),
        ('readmodel', 'runtime_control', 'publication_enabled', 'publication enabled'),
        ('readmodel', 'runtime_control', 'affiliate_links_enabled', 'affiliate links enabled'),
        ('readmodel', 'runtime_control', 'generation', 'generation'),
        ('readmodel', 'runtime_control', 'reason_code', 'reason code'),
        ('readmodel', 'runtime_control', 'expires_at', 'expires at'),
        ('readmodel', 'runtime_control', 'projected_at', 'projected at')
    )
    SELECT pg_catalog.count(*) INTO mismatch_count
    FROM expected
    LEFT JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.nspname = expected.schema_name
    LEFT JOIN pg_catalog.pg_class AS relation
      ON relation.relnamespace = namespace.oid
     AND relation.relname = expected.table_name AND relation.relkind = 'r'
    LEFT JOIN pg_catalog.pg_attribute AS attribute
      ON attribute.attrelid = relation.oid
     AND attribute.attname = expected.column_name
     AND attribute.attnum > 0 AND attribute.attisdropped IS FALSE
    WHERE attribute.attnum IS NULL
       OR pg_catalog.col_description(relation.oid, attribute.attnum)
          IS DISTINCT FROM expected.description;
    IF mismatch_count <> 0 THEN
        RAISE EXCEPTION 'ST0305_COLUMN_COMMENT_MISMATCH';
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_catalog.pg_constraint
        WHERE conname = ANY(ARRAY['fk_iam_break_glass_record_incident_id', 'fk_publishing_publication_event_release_id', 'fk_publishing_rollback_record_incident_id'])
    ) THEN
        RAISE EXCEPTION 'ST0305_DEFERRED_FOREIGN_KEY_MISMATCH';
    END IF;
    IF (
        SELECT pg_catalog.count(*) FROM pg_catalog.pg_constraint
        WHERE conname = ANY(ARRAY['fk_publishing_public_route_publication_id', 'fk_publishing_publication_candidate_publication_snapshot_id', 'fk_publishing_publication_current_route_id', 'fk_publishing_publication_snapshot_publication_candidate_id'])
          AND contype = 'f' AND condeferrable IS TRUE AND condeferred IS TRUE
    ) <> 4 THEN
        RAISE EXCEPTION 'ST0305_CYCLIC_FOREIGN_KEY_MISMATCH';
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_catalog.pg_class AS relation
        JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
        CROSS JOIN LATERAL pg_catalog.aclexplode(
            COALESCE(relation.relacl, pg_catalog.acldefault('r', relation.relowner))
        ) AS acl
        WHERE namespace.nspname = ANY(ARRAY['publishing', 'freshness', 'analytics', 'finance', 'readmodel'])
          AND relation.relkind IN ('r','v') AND acl.grantee <> relation.relowner
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.pg_proc AS routine
        JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
        CROSS JOIN LATERAL pg_catalog.aclexplode(
            COALESCE(routine.proacl, pg_catalog.acldefault('f', routine.proowner))
        ) AS acl
        WHERE namespace.nspname = ANY(ARRAY['publishing', 'freshness', 'analytics', 'finance', 'readmodel'])
          AND acl.grantee <> routine.proowner
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.pg_default_acl AS default_acl
        LEFT JOIN pg_catalog.pg_namespace AS namespace
          ON namespace.oid = default_acl.defaclnamespace
        WHERE default_acl.defaclnamespace = 0
           OR namespace.nspname = ANY(ARRAY['publishing', 'freshness', 'analytics', 'finance', 'readmodel'])
    ) THEN
        RAISE EXCEPTION 'ST0305_PUBLIC_OR_DEFAULT_ACL_MISMATCH';
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_catalog.pg_class AS relation
        JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
        WHERE namespace.nspname = ANY(ARRAY['publishing', 'freshness', 'analytics', 'finance', 'readmodel'])
          AND relation.relkind = 'r'
          AND (relation.relrowsecurity IS TRUE OR relation.relforcerowsecurity IS TRUE)
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.pg_policy AS policy_record
        JOIN pg_catalog.pg_class AS relation ON relation.oid = policy_record.polrelid
        JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
        WHERE namespace.nspname = ANY(ARRAY['publishing', 'freshness', 'analytics', 'finance', 'readmodel'])
    ) THEN
        RAISE EXCEPTION 'ST0305_RLS_BOUNDARY_MISMATCH';
    END IF;

    IF (SELECT pg_catalog.count(*) FROM pg_catalog.pg_trigger
        WHERE tgname = ANY(ARRAY['trg_publishing_approval_guard', 'trg_publishing_candidate_guard', 'trg_publishing_publication_guard', 'trg_publishing_review_assignment_touch', 'trg_publishing_publication_candidate_touch', 'trg_publishing_publication_touch', 'trg_publishing_public_route_touch', 'trg_freshness_refresh_schedule_touch', 'trg_finance_revenue_import_touch', 'trg_finance_commission_touch', 'trg_publishing_review_decision_immutable', 'trg_publishing_publication_snapshot_immutable', 'trg_publishing_publication_event_immutable', 'trg_analytics_anonymous_event_immutable', 'trg_analytics_affiliate_click_event_immutable', 'trg_finance_commission_event_immutable', 'trg_finance_cost_allocation_immutable'])
          AND tgisinternal IS FALSE) <> 17 THEN
        RAISE EXCEPTION 'ST0305_TRIGGER_IDENTITY_MISMATCH';
    END IF;
END
$raos_st0305_validation$;

SELECT 'PASS'::pg_catalog.text AS status,
       39::pg_catalog.int4 AS tables,
       629::pg_catalog.int4 AS columns,
       150::pg_catalog.int4 AS installed_foreign_keys,
       17::pg_catalog.int4 AS triggers;
